#!/usr/bin/env bash
set -Eeuo pipefail
TF_ROOT=${TF_ROOT:-/opt/tunnelforge}; TF_ETC=${TF_ETC:-/etc/tunnelforge}; TF_VAR=${TF_VAR:-/var/lib/tunnelforge}; TF_LOG_DIR=${TF_LOG_DIR:-/var/log/tunnelforge}; TF_CONFIG=${TF_CONFIG:-$TF_ETC/config.toml}; TF_STATE=${TF_STATE:-$TF_VAR/state.json}; TF_HISTORY=${TF_HISTORY:-$TF_VAR/history.jsonl}; TF_LOG=${TF_LOG:-$TF_LOG_DIR/tunnelforge.log}; TF_SECRETS=${TF_SECRETS:-$TF_ETC/secrets}; TF_HEALTH_TOKEN_FILE=${TF_HEALTH_TOKEN_FILE:-$TF_SECRETS/health.token}
log(){ local level=${1:-INFO}; shift || true; printf '%s level=%s %s\n' "$(date -Is)" "$level" "$*" | tee -a "$TF_LOG" >&2; }; die(){ log ERROR "$*"; exit 1; }; need_root(){ [[ ${EUID:-$(id -u)} -eq 0 ]] || die "root privileges required"; }; need_cmd(){ command -v "$1" >/dev/null 2>&1 || die "missing command: $1"; }
atomic_write(){ local target=$1 mode=${2:-600} tmp; tmp=$(mktemp "${target}.tmp.XXXXXX"); cat >"$tmp"; chmod "$mode" "$tmp"; mv -f "$tmp" "$target"; }
validate_ipv4(){ local ip=$1 IFS=. a; read -ra a <<<"$ip"; [[ ${#a[@]} -eq 4 ]] || return 1; local x; for x in "${a[@]}"; do [[ $x =~ ^[0-9]{1,3}$ ]] || return 1; ((10#$x<=255)) || return 1; done; }; validate_port(){ [[ $1 =~ ^[0-9]+$ ]] && (( $1>=1 && $1<=65535 )); }; port_free(){ ! ss -H -lnt 2>/dev/null | awk '{print $4}' | grep -Eq ":$1$"; }; service_active(){ systemctl is-active --quiet "$1"; }; owned_unit(){ [[ $1 == tunnelforge-* ]]; }; stop_owned_unit(){ owned_unit "$1" || die "refusing to stop non-TunnelForge unit: $1"; systemctl disable --now "$1" >/dev/null 2>&1 || true; }; rand_token(){ if command -v openssl >/dev/null; then openssl rand -hex 32; else head -c32 /dev/urandom|od -An -tx1|tr -d ' \n'; fi; }
